 66	package shop.order;
 67	
 68	import com.fasterxml.jackson.databind.JsonNode;
 69	import shop.ApiException;
 70	import shop.checkout.CheckoutCalculator;
 71	import shop.checkout.CheckoutRequest;
 72	import shop.checkout.Summary;
 73	import shop.notification.NotificationType;
 74	import shop.notification.Notifier;
 75	import shop.persistence.Store;
 76	import shop.persistence.Tx;
 77	
 78	import java.time.Clock;
 79	import java.time.Duration;
 80	import java.time.Instant;
 81	import java.time.format.DateTimeParseException;
 82	import java.time.temporal.ChronoUnit;
 83	import java.util.Comparator;
 84	import java.util.List;
 85	import java.util.UUID;
 86	
 87	public final class OrderService {
 88	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 89	
 90	    private final Store store;
 91	    private final CheckoutCalculator calculator;
 92	    private final Notifier notifier;
 93	    private final List<PaymentConfirmationReaction> reactions;
 94	    private final Clock clock;
 95	
 96	    public OrderService(Store store, CheckoutCalculator calculator, Notifier notifier,
 97	                        List<PaymentConfirmationReaction> reactions, Clock clock) {
 98	        this.store = store;
 99	        this.calculator = calculator;
100	        this.notifier = notifier;
101	        this.reactions = reactions;
102	        this.clock = clock;
103	    }
104	
105	    public Summary summary(CheckoutRequest request) {
106	        return store.inTransaction(tx -> calculator.calculate(tx, request));
107	    }
108	
109	    public Order register(CheckoutRequest request) {
110	        return store.inTransaction(tx -> {
111	            Summary summary = calculator.calculate(tx, request);
112	            tx.customers().createIfAbsent(request.cpf());
113	            List<OrderItem> items = request.items().stream()
114	                    .map(item -> new OrderItem(item.sku(), item.quantity())).toList();
115	            Order order = new Order(UUID.randomUUID().toString(), request.cpf(), request.email(),
116	                    OrderStatus.AWAITING_PAYMENT, clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items, null);
117	            tx.orders().insert(order);
118	            return order;
119	        });
120	    }
121	
122	    public Order get(String id) {
123	        return store.inTransaction(tx -> tx.orders().find(id).orElseThrow(OrderService::notFound));
124	    }
125	
126	    private record PaymentResult(Order order, String refusal) {
127	    }
128	
129	    public Order confirmPayment(String id, JsonNode body) {
130	        PaymentResult result = store.inTransaction(tx -> {
131	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
132	            String transactionId = CheckoutRequest.text(body, "transactionId");
133	            String paidAtText = CheckoutRequest.text(body, "paidAt");
134	            if (transactionId == null || transactionId.isBlank() || paidAtText == null) {
135	                throw ApiException.unprocessable("INVALID_ORDER");
136	            }
137	            Instant paidAt;
138	            try {
139	                paidAt = Instant.parse(paidAtText);
140	            } catch (DateTimeParseException e) {
141	                throw ApiException.unprocessable("INVALID_ORDER");
142	            }
143	            var previous = tx.paymentNotices().find(id, transactionId);
144	            if (previous.isPresent()) {
145	                return new PaymentResult(order, previous.get().refusalCode());
146	            }
147	            requireTransition(order, OrderStatus.PAID);
148	            if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_WINDOW) > 0) {
149	                return refuse(tx, order, transactionId, "ORDER_EXPIRED");
150	            }
151	            if (!reserveStock(tx, order)) {
152	                return refuse(tx, order, transactionId, "INSUFFICIENT_STOCK");
153	            }
154	            Order paid = order.withStatus(OrderStatus.PAID);
155	            tx.orders().update(paid);
156	            reactions.forEach(reaction -> reaction.onPaid(tx, paid));
157	            tx.paymentNotices().insert(new PaymentNotice(id, transactionId, null));
158	            return new PaymentResult(paid, null);
159	        });
160	        if (result.refusal() != null) {
161	            throw ApiException.conflict(result.refusal());
162	        }
163	        return result.order();
164	    }
165	
166	    public Order ship(String id, JsonNode body) {
167	        return store.inTransaction(tx -> {
168	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
169	            String trackingCode = CheckoutRequest.text(body, "trackingCode");
170	            if (trackingCode == null || trackingCode.isBlank()) {
171	                throw ApiException.unprocessable("INVALID_ORDER");
172	            }
173	            requireTransition(order, OrderStatus.SHIPPED);
174	            Order shipped = order.withStatus(OrderStatus.SHIPPED).withTrackingCode(trackingCode);
175	            tx.orders().update(shipped);
176	            notifier.notify(tx, shipped, NotificationType.ORDER_SHIPPED);
177	            return shipped;
178	        });
179	    }
180	
181	    public Order deliver(String id) {
182	        return store.inTransaction(tx -> {
183	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
184	            requireTransition(order, OrderStatus.DELIVERED);
185	            Order delivered = order.withStatus(OrderStatus.DELIVERED);
186	            tx.orders().update(delivered);
187	            return delivered;
188	        });
189	    }
190	
191	    public Order cancel(String id) {
192	        return store.inTransaction(tx -> {
193	            Order order = tx.orders().lock(id).orElseThrow(OrderService::notFound);
194	            requireTransition(order, OrderStatus.CANCELLED);
195	            return cancelOrder(tx, order);
196	        });
197	    }
198	
199	    private PaymentResult refuse(Tx tx, Order order, String transactionId, String code) {
200	        Order cancelled = cancelOrder(tx, order);
201	        tx.paymentNotices().insert(new PaymentNotice(order.id(), transactionId, code));
202	        return new PaymentResult(cancelled, code);
203	    }
204	
205	    /** Cancels the order, undoing what the payment did when it had been confirmed. */
206	    private Order cancelOrder(Tx tx, Order order) {
207	        if (order.status().paymentConfirmed()) {
208	            releaseStock(tx, order);
209	            reactions.forEach(reaction -> reaction.onPaidOrderCancelled(tx, order));
210	        }
211	        Order cancelled = order.withStatus(OrderStatus.CANCELLED);
212	        tx.orders().update(cancelled);
213	        notifier.notify(tx, cancelled, NotificationType.ORDER_CANCELLED);
214	        return cancelled;
215	    }
216	
217	    /** Locks the products (always in SKU order) and takes the stock only if every item is covered. */
218	    private boolean reserveStock(Tx tx, Order order) {
219	        List<OrderItem> items = sorted(order);
220	        for (OrderItem item : items) {
221	            boolean enough = tx.products().lock(item.sku()).map(product -> product.stock() >= item.quantity()).orElse(false);
222	            if (!enough) {
223	                return false;
224	            }
225	        }
226	        items.forEach(item -> tx.products().adjustStock(item.sku(), -item.quantity()));
227	        return true;
228	    }
229	
230	    private void releaseStock(Tx tx, Order order) {
231	        sorted(order).forEach(item -> tx.products().adjustStock(item.sku(), item.quantity()));
232	    }
233	
234	    private static List<OrderItem> sorted(Order order) {
235	        return order.items().stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
236	    }
237	
238	    private static void requireTransition(Order order, OrderStatus target) {
239	        if (!order.status().canMoveTo(target)) {
240	            throw ApiException.conflict("OPERATION_NOT_ALLOWED");
241	        }
242	    }
243	
244	    private static ApiException notFound() {
245	        return ApiException.notFound("ORDER_NOT_FOUND");
246	    }
247	}

